import{_ as i,l as o,o as e,c as l,v as t,p as E,x as n,d as s,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const q=JSON.parse('{"title":"净股票发行","description":"","frontmatter":{"title":"净股票发行","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/net-issuance.md","filePath":"quant/net-issuance.md","lastUpdated":1789023840000}'),A={name:"quant/net-issuance.md"};function h(c,a,m,u,f,_){const r=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="净股票发行" tabindex="-1">净股票发行 <a class="header-anchor" href="#净股票发行" aria-label="Permalink to &quot;净股票发行&quot;">​</a></h1><div class="epigraph"><p>净发行股份多的公司，随后股票收益显著偏低；回购与缩股的一侧则偏高。融资行为本身携带价格信息。</p><footer>—— 综合 Pontiff–Woodgate 的股份变动、Daniel–Titman 的复合发行与 SEO/回购文献</footer></div><p>公司可以发新股、配股、行使期权、换股并购，也可以回购、注销。净股票发行把这些活动收成一个数字：股份或市值中「不是靠价格涨出来的那一部分」。Pontiff 与 Woodgate 证明截面上净发行预测收益；Daniel 与 Titman 的复合股权发行用市值增长减股票收益来抓同一件事；Loughran–Ritter 的 SEO 长期弱势、Ikenberry 等人的回购长期强势是事件研究版。本篇写可排序的净发行因子，以及它和<a href="/quant/asset-growth">资产增长</a>、<a href="/quant/qmj">QMJ</a> 分红块的重叠。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若市场对融资决策即时、正确定价，则发行之后不应留下负 α，回购之后不应留下正 α。实证上方向稳定：净发行高，随后收益低。解释有两条主路。市场择时：管理层在高估时发行、低估时回购，投资者反应不足。投资/q：发行是为了给低贴现率的项目筹资，随后收益低是贴现率的结果，与 CMA 同向。两条都可以产生同一符号，必须用控制变量拆。</p><p>会计上还要分清：净发行不是「增发公告日的折价」，而是形成期之后一年的持有收益。事件研究的 SEO 折价是发行日微观结构；因子是特征。把询价过低写成 Pontiff–Woodgate 的 α，频率错了。</p><h3 id="三种常用度量不要混用" tabindex="-1">三种常用度量不要混用 <a class="header-anchor" href="#三种常用度量不要混用" aria-label="Permalink to &quot;三种常用度量不要混用&quot;">​</a></h3><p>股份变动：\\(\\Delta N/N\\)，用拆分调整后的流通股或发行在外股。现金发行：股权融资现金流减回购，除以市值。复合发行（Daniel–Titman）：</p> \\[\\mathrm{CEI}_{t}=\\log\\Bigl(\\frac{ME_{t}}{ME_{t-k}}\\Bigr)-\\,r_{t-k,t} \\]<p>即市值的对数增长减去区间股票收益，剩下的就是净发行对市值的贡献。\\(k\\) 常用五年。复合发行能抓住换股并购、期权稀释等不进现金流的股份，但对拆分与红利再投资的处理要小心。三种度量相关高，极端组持仓仍会不同：期权稀释重的科技股可以股份增、现金净回购。</p><p><span class="marginnote">QMJ 的分红块把低净发行当高质量。那是把本因子的一侧写进质量分数。复制 QMJ 却声称「独立于发行异常」，必须先去掉 payout 块再检验。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每年 6 月用过去一年或五年的净发行排序，NYSE 分位，价值加权多空：多回购/低发行，空高发行。金融与公用事业融资含义不同，常剔除或单独做。检验：三因子、四因子、<a href="/quant/ff5">五因子</a> 与 q 因子。投资因子会吸收一块，因为扩张常靠发股；控制 \\(\\Delta A/A\\) 之后若仍显著，才有独立的融资信息。</p><p>事件研究与因子应分开表：SEO、IPO、回购的日历时间组合，与年度特征排序不是同一策略。IPO 的长期弱势还混有锁定期与做市，不宜直接并进净发行十分位。换手低于动量、高于纯价值：一年发行事件稀疏，但大额 SEO 会让空头换手集中。</p><h3 id="资产增长的融资边" tabindex="-1">资产增长的融资边 <a class="header-anchor" href="#资产增长的融资边" aria-label="Permalink to &quot;资产增长的融资边&quot;">​</a></h3><p>资产负债表恒等式：资产增长 = 负债增长 + 权益增长（含留存）。权益增长里有盈利留存，也有净发行。<a href="/quant/investment-factor">投资因子</a> 用 \\(\\Delta A\\)，净发行只用权益融资边。把两者同时放进回归，共线会让 t 值打架；更干净的是把 \\(\\Delta A\\) 分解成经营资产增长与融资，或先正交再排序。Fama–French 的「解剖异常」把净发行列为难以被三因子吸收的特征之一，五因子的 CMA、RMW 能吃掉一部分，未必吃完。</p>',16)),(e(),E(d,null,{default:n(()=>[p(r,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20SEO%5B%22%E5%A2%9E%E5%8F%91%20%2F%20%E9%85%8D%E8%82%A1%20%2F%20%E6%8D%A2%E8%82%A1%22%5D%20--%3E%20NI%5B%22%E5%87%80%E5%8F%91%E8%A1%8C%E5%BA%A6%E9%87%8F%22%5D%0A%20%20RP%5B%22%E5%9B%9E%E8%B4%AD%20%2F%20%E6%B3%A8%E9%94%80%22%5D%20--%3E%20NI%0A%20%20OPT%5B%22%E6%9C%9F%E6%9D%83%E4%B8%8E%E7%A8%80%E9%87%8A%22%5D%20--%3E%20CEI%5B%22%E5%A4%8D%E5%90%88%E5%8F%91%E8%A1%8C%20CEI%22%5D%0A%20%20NI%20--%3E%20CEI%0A%20%20CEI%20--%3E%20LS%5B%22%E4%BD%8E%E5%8F%91%E8%A1%8C%E5%87%8F%E9%AB%98%E5%8F%91%E8%A1%8C%22%5D%0A%20%20DA%5B%22%CE%94%E8%B5%84%E4%BA%A7%22%5D%20--%3E%20CMA%5B%22CMA%20%2F%20%E8%B5%84%E4%BA%A7%E5%A2%9E%E9%95%BF%22%5D%0A%20%20NI%20--%3E%20CMA%0A%20%20LS%20--%3E%20DIAG%5B%22%E6%8E%A7%E5%88%B6%20CMA%E3%80%81RMW%E3%80%81%E5%8A%A8%E9%87%8F%22%5D%0A%20%20CMA%20--%3E%20DIAG%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>择时：高市值相对账面或相对过去时发行，等于公司站在价值空头一侧；若价值本身有溢价，净发行可以是价值的代理。但控制 B/M 之后发行往往仍显著，说明不只是价值。反应不足：投资者对稀释与「为什么现在要钱」反应慢，随后盈利或倍数下滑。风险：高发行公司投资重、久期长，要求收益低——与 q 理论一致，预测发行溢价在高投资格子里更弱（已被投资解释）。</p><p>行为与风险的分界在治理与用途：为NPV为负的并购发股，更像代理问题；为产能扩张发股，更像 q。交易上两者都是空头。回购一侧还含有自由现金流吐出与EPS管理，短期可能与应计同向（回购抬 EPS），一年持有期则通常为正。</p><h3 id="与动量、pead-的短暂冲突" tabindex="-1">与动量、PEAD 的短暂冲突 <a class="header-anchor" href="#与动量、pead-的短暂冲突" aria-label="Permalink to &quot;与动量、PEAD 的短暂冲突&quot;">​</a></h3><p>发行公告前后常有负的事件收益，但净发行因子的形成已滞后到财报与股份统计可获得之后，不靠公告日。刚 SEO 的股票可能进入动量输家，空头会与 WML 空头重叠。PEAD 的负意外公司也可能被迫融资。诊断应看持仓重叠率，而不是只看因子收益相关。</p><p><span class="marginnote">A 股定增、配股、可转债与「减持」并存，净发行要用股份或募集资金口径，不能只用现金表里的「吸收投资收到的现金」。壳与借壳会制造一次性股份爆炸，等权空头会被少数点主导。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>空头是高发行公司，不一定好借；并购换股的锁定期让供给与借券同时变差。回购多头要排除窗口期回购的微观结构。税率与指数纳入会影响回购的股东收益。不要把「股东收益率=股利+回购」的多头直接叫做本因子——那还混进了股利政策，与 Carry 的股指腿、与 QMJ 分红块纠缠。</p><p>不要在五因子回归里同时塞净发行、CMA、应计、资产增长四条高度相关的扩张腿还报告四个 α。先选一条符合故事的主排序键，其余做稳健性。容量：价值加权的大盘回购多头可交易；等权小盘增发空头账面最美、实现最差。</p><p><span class="marginnote">出处分层：股份变动见 Pontiff &amp; Woodgate, Journal of Finance, 2008；复合发行见 Daniel &amp; Titman, Journal of Finance, 2006；SEO 长期表现见 Loughran &amp; Ritter。Fama–French 2008 的异常解剖把净发行单独列出。不要伪造一个「FF 净发行因子」编号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>净发行高预测低收益；度量可以是股份变动、现金发行或复合 CEI。</li><li>与资产增长、QMJ 分红块部分同义，须拆开再谈独立 α。</li><li>机制可以是择时、反应不足或 q 理论下的投资融资。</li><li>等权小盘增发空头不可当作容量；A 股要用当地融资工具口径。</li><li>出处：Pontiff &amp; Woodgate, 2008；Daniel &amp; Titman, 2006。</li></ul>',12))])}const P=i(A,[["render",h]]);export{q as __pageData,P as default};
